'use strict';

// MODULES //

var tape = require( 'tape' );
var abs = require( '@stdlib/math/base/special/abs' );
var atan = require( '@stdlib/math/base/special/atan' );
var EPS = require( '@stdlib/constants/float64/eps' );
var incrnanmmaape = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmmaape, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5.0,
		0.0,
		3.14,
		true,
		null,
		void 0,
		NaN,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanmmaape( value );
		};
	}
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmmaape( 3 ), 'function', 'returns expected value' );
	t.end();
});

tape( 'the accumulator function computes a moving mean arctangent absolute percentage error incrementally', function test( t ) {
	var expected;
	var actual;
	var delta;
	var data;
	var acc;
	var tol;
	var N;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, 1.0 ],
		[ 5.0, 2.0 ],
		[ 4.0, 4.0 ],
		[ 3.0, 10.0 ],
		[ 4.0, 5.0 ]
	];
	N = data.length;

	acc = incrnanmmaape( 3 );

	// Note: manually computed
	expected = [
		(1.0/1.0)*( atan(1.0/3.0) ),
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) ),
		(1.0/3.0)*( atan(3.0/2.0)+atan(0.0/4.0)+atan(7.0/10.0) ),
		(1.0/3.0)*( atan(0.0/4.0)+atan(7.0/10.0)+atan(1.0/5.0) )
	];
	for ( i = 0; i < N; i++ ) {
		actual = acc( data[i][0], data[i][1] );
		if ( actual === expected[i] ) {
			t.strictEqual( actual, expected[i], 'returns expected value' );
		} else {
			delta = abs( expected[i] - actual );
			tol = 1.0 * EPS * abs( expected[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. Actual: '+actual+'. Expected: '+expected[i]+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean arctangent absolute percentage error', function test( t ) {
	var data;
	var acc;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, 5.0 ],
		[ 19.0, 10.0 ]
	];
	acc = incrnanmmaape( 2 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[i][0], data[i][1] );
	}
	t.strictEqual( acc(), 0.5*( atan(2.0/5.0)+atan(9.0/10.0) ), 'returns expected value' );
	t.end();
});

tape( 'if data has yet to be provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmmaape( 3 );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function ignores NaN values in the first argument', function test( t ) {
	var expected;
	var delta;
	var data;
	var acc;
	var tol;
	var v;
	var i;

	// Test data with NaN values in the first position (forecast values)
	data = [
		[ 2.0, 3.0 ],
		[ NaN, 1.0 ],
		[ 3.0, 1.0 ],
		[ 5.0, 2.0 ],
		[ NaN, 4.0 ],
		[ 4.0, 4.0 ]
	];

	acc = incrnanmmaape( 3 );

	// Expected: NaN values should be skipped, window continues sliding

	// Window: [(2.0,3.0)]

	// Window: [(2.0,3.0)] - NaN skipped, window has only 1 value

	// Window: [(2.0,3.0), (3.0,1.0)]

	// Window: [(2.0,3.0), (3.0,1.0), (5.0,2.0)] - window full, all 3 values

	// Window: [(2.0,3.0), (3.0,1.0), (5.0,2.0)] - NaN skipped, window unchanged

	// Window: [(3.0,1.0), (5.0,2.0), (4.0,4.0)]
	expected = [
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)]
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)] - NaN ignored
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),                      // [(2.0,3.0), (3.0,1.0)]
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),        // [(2.0,3.0), (3.0,1.0), (5.0,2.0)]
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),        // [(2.0,3.0), (3.0,1.0), (5.0,2.0)] - NaN ignored, window unchanged
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) )         // [(3.0,1.0), (5.0,2.0), (4.0,4.0)]
	];

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[i][0], data[i][1] );
		if ( v === expected[i] ) {
			t.strictEqual( v, expected[i], 'returns expected value for pair '+i );
		} else {
			delta = abs( expected[i] - v );
			tol = 2.0 * EPS * abs( expected[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance for pair '+i+'. Actual: '+v+'. Expected: '+expected[i]+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'the accumulator function ignores NaN values in the second argument', function test( t ) {
	var expected;
	var delta;
	var data;
	var acc;
	var tol;
	var v;
	var i;

	// Test data with NaN values in the second position (actual values)
	data = [
		[ 2.0, 3.0 ],
		[ 3.0, NaN ],
		[ 3.0, 1.0 ],
		[ 5.0, 2.0 ],
		[ 4.0, NaN ],
		[ 4.0, 4.0 ]
	];

	acc = incrnanmmaape( 3 );

	// Expected: NaN values should be skipped, window continues sliding
	expected = [
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)]
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)] - NaN ignored
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),                      // [(2.0,3.0), (3.0,1.0)]
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),        // [(2.0,3.0), (3.0,1.0), (5.0,2.0)]
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),        // [(2.0,3.0), (3.0,1.0), (5.0,2.0)] - NaN ignored, window unchanged
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) )         // [(3.0,1.0), (5.0,2.0), (4.0,4.0)]
	];

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[i][0], data[i][1] );
		if ( v === expected[i] ) {
			t.strictEqual( v, expected[i], 'returns expected value for pair '+i );
		} else {
			delta = abs( expected[i] - v );
			tol = 2.0 * EPS * abs( expected[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance for pair '+i+'. Actual: '+v+'. Expected: '+expected[i]+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});

