tape( 'when all values in the window are NaN, the accumulator function returns `null`', function test( t ) {
	var data;
	var acc;
	var v;
	var i;

	data = [
		[ NaN, 1.0 ],
		[ NaN, NaN ],
		[ 1.0, NaN ]
	];

	acc = incrnanmmaape( 3 );

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[i][0], data[i][1] );
		t.strictEqual( v, null, 'returns null when all values are NaN' );
	}
	t.end();
});

tape( 'the accumulator function correctly handles a mix of NaN and non-NaN values', function test( t ) {
	var expected;
	var delta;
	var data;
	var acc;
	var tol;
	var v;
	var i;

	data = [
		[ NaN, 3.0 ],
		[ 2.0, 3.0 ],
		[ NaN, NaN ],
		[ 3.0, 1.0 ],
		[ 5.0, NaN ],
		[ NaN, 2.0 ],
		[ 5.0, 2.0 ],
		[ 4.0, 4.0 ]
	];

	acc = incrnanmmaape( 3 );

	expected = [
		null,                                                           // [] - NaN ignored, nothing yet
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)]
		(1.0/1.0)*( atan(1.0/3.0) ),                                    // [(2.0,3.0)] - NaN ignored
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),                      // [(2.0,3.0), (3.0,1.0)]
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),                      // [(2.0,3.0), (3.0,1.0)] - NaN ignored
		(1.0/2.0)*( atan(1.0/3.0)+atan(2.0/1.0) ),                      // [(2.0,3.0), (3.0,1.0)] - NaN ignored
		(1.0/3.0)*( atan(1.0/3.0)+atan(2.0/1.0)+atan(3.0/2.0) ),        // [(2.0,3.0), (3.0,1.0), (5.0,2.0)]
		(1.0/3.0)*( atan(2.0/1.0)+atan(3.0/2.0)+atan(0.0/4.0) )         // [(3.0,1.0), (5.0,2.0), (4.0,4.0)]
	];

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[i][0], data[i][1] );
		if ( expected[i] === null ) {
			t.strictEqual( v, null, 'returns null for pair '+i );
		} else if ( v === expected[i] ) {
			t.strictEqual( v, expected[i], 'returns expected value for pair '+i );
		} else {
			delta = abs( expected[i] - v );
			tol = 2.0 * EPS * abs( expected[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance for pair '+i+'. Actual: '+v+'. Expected: '+expected[i]+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});
